messages.content:
Tool response:
Tool: transfer_asset_custodian_and_location
Description: Update the custodian and location of a specified asset, recording the change in history with a reason.
Parameters:
    {
      "type": "object",
      "properties": {
        "asset_tag": {
          "type": "string",
          "description": "Unique identifier of the asset to be transferred",
          "title": "Asset Tag"
        },
        "new_custodian_name": {
          "type": "string",
          "title": "New Custodian Name"
        },
        "new_location_name": {
          "type": "string",
          "title": "New Location Name"
        },
        "reason": {
          "type": "string",
          "title": "Reason"
        }
      },
      "required": [
        "asset_tag",
        "new_custodian_name",
        "new_location_name",
        "reason"
      ]
    }
